import {prepareStyledSurface} from './styled-surface.js';
import {GUIDE_ART,GUIDE_NAMES} from './approved-guide-model.js';
import {approvedSkillGlyph} from './approved-talent-icons.js';
export function createApprovedGuideView({document,onPick,onToggle,onAction,onExit,onRoute}){
 const root=document.createElement('div');root.id='hubGuideOverlay';root.className='approved-guide approved-service-host';root.hidden=true;root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','Tutorial');
 const topLayer=typeof root.showPopover==='function';if(topLayer)root.setAttribute('popover','manual');
 if(!document.getElementById('approvedGuideFonts')){const fonts=document.createElement('style');fonts.id='approvedGuideFonts';fonts.textContent="@font-face{font-family:GVGuideDisplay;src:url('assets/menu-fonts/Fredoka-600-Static.ttf');font-weight:600}@font-face{font-family:GVGuideBody;src:url('assets/menu-fonts/Nunito-600-Static.ttf');font-weight:600}";document.head.append(fonts);}
 const shadow=root.attachShadow({mode:'open'}),style=document.createElement('link');style.rel='stylesheet';style.href='approved-guide-ui.css';shadow.append(style);prepareStyledSurface(root,shadow);
 const content=document.createElement('div');content.innerHTML='<div id="gv-tutorial-guide"><section class="tg-window" aria-label="Guia do Tutorial"><header class="tg-head"><img src="assets/refuge-night-v3/scroll.png" alt=""><h2>Tutorial</h2><button type="button" class="tg-button tg-close" aria-label="Fechar Tutorial">×</button></header><div class="tg-learning"><button type="button" class="tg-button tg-learning-route" data-route="tour"><img src="assets/hud-v5/home.png" alt=""><span>Primeira expedição<small>Conheça o refúgio</small></span><span class="tg-arrow" aria-hidden="true">›</span></button><button type="button" class="tg-button tg-learning-route" data-route="training">'+approvedSkillGlyph('ear')+'<span>Treino de ritmo<small>Golpe · fôlego · itens</small></span><span class="tg-arrow" aria-hidden="true">›</span></button></div><div class="tg-workspace"><nav class="tg-places" aria-label="Locais do refúgio"></nav><section class="tg-detail" aria-label="Local selecionado"><header class="tg-selected"><img class="tg-selected-art" alt=""><h3></h3><button type="button" class="tg-button tg-info" aria-label="Ver orientação completa" aria-expanded="false">i</button></header><div class="tg-copy" aria-live="polite"><p class="tg-summary"></p><p class="tg-context"></p><p class="tg-run-note" hidden>Volte ao refúgio para abrir.</p></div><button type="button" class="tg-button tg-primary" data-primary="true"></button></section></div></section></div>';
 shadow.append(...content.childNodes);document.body.append(root);const q=s=>shadow.querySelector(s),all=s=>[...shadow.querySelectorAll(s)],surface=q('#gv-tutorial-guide');
 for(const [id,name]of Object.entries(GUIDE_NAMES)){const b=document.createElement('button');b.type='button';b.className='tg-button tg-place';b.dataset.place=id;b.setAttribute('aria-pressed','false');const img=document.createElement('img');img.alt='';if(GUIDE_ART[id])img.src=GUIDE_ART[id];const label=document.createElement('span');label.textContent=id==='tree'?'Árvore':name;b.append(img,label);q('.tg-places').append(b);}
 all('button').forEach(b=>b.classList.add('cursor-interaction'));
 let disposed=false;const motion=document.defaultView.matchMedia?.('(prefers-reduced-motion: reduce)');
 function hide(){if(topLayer&&root.matches(':popover-open'))root.hidePopover();root.hidden=true;}
 function show(model){if(disposed||!model)return;const opening=root.hidden;root.hidden=false;if(topLayer&&!root.matches(':popover-open'))root.showPopover();
  all('[data-place]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.place===model.id)));
  q('[data-place="statue"] img').src=model.statueImage;q('.tg-selected h3').textContent=model.name;q('.tg-selected-art').src=model.image;
  q('.tg-info').setAttribute('aria-expanded',String(model.expanded));q('.tg-info').setAttribute('aria-label',model.expanded?'Resumir orientação':'Ver orientação completa');q('.tg-summary').textContent=model.expanded?model.text:model.summary;q('.tg-context').textContent=model.expanded?model.status:model.context;q('.tg-copy').scrollTop=0;
  q('.tg-run-note').hidden=!model.inRun;q('.tg-primary').textContent=model.inRun?'Fechar':'Abrir '+model.name+'  ›';q('[data-route="tour"]').disabled=model.inRun;q('[data-route="tour"] small').textContent=model.inRun?'No refúgio':'Conheça o refúgio';layout();if(opening)q('.tg-close').focus({preventScroll:true});
 }
 function layout(){if(root.hidden)return;const soft=String(document.hidden||document.getElementById('effects')?.getAttribute('aria-pressed')==='false'||!!motion?.matches);if(surface.dataset.soft!==soft)surface.dataset.soft=soft;}
 function click(e){const b=e.target.closest('button');if(!b||b.disabled||disposed)return;if(b.dataset.place)onPick(b.dataset.place);else if(b.dataset.route)onRoute(b.dataset.route);else if(b.matches('.tg-info'))onToggle();else if(b.matches('.tg-primary'))onAction();else if(b.matches('.tg-close'))onExit();}
 function key(e){if(root.hidden||disposed)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();onExit();return;}if(e.repeat&&['Space','Enter'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();return;}if(e.code==='Tab'){const controls=all('button').filter(b=>!b.disabled&&!b.hidden&&b.offsetParent!==null);if(controls.length){const i=controls.indexOf(shadow.activeElement||document.activeElement);e.preventDefault();controls[(i+(e.shiftKey?-1:1)+controls.length)%controls.length].focus();}return;}if(!root.contains(e.target)){e.preventDefault();e.stopImmediatePropagation();}}
 const respond=e=>{const b=e.target.closest('button');if(!b||b.disabled||b.contains(e.relatedTarget)||surface.dataset.soft==='true')return;b.classList.remove('tg-respond');void b.offsetWidth;b.classList.add('tg-respond');};
 shadow.addEventListener('click',click);shadow.addEventListener('pointerover',respond);document.addEventListener('keydown',key,true);
 return {root,show,hide,layout,contains:node=>root.contains(node)||shadow.contains(node),destroy(){hide();disposed=true;document.removeEventListener('keydown',key,true);shadow.removeEventListener('click',click);shadow.removeEventListener('pointerover',respond);root.remove();}};
}
